+	simd_float4x4 origin_from_controller_anchor_simd = ar_anchor_get_origin_from_anchor_transform(p_controller_anchor);
+	Transform3D origin_from_controller_anchor = MTL::simd_to_transform3D(origin_from_controller_anchor_simd);
+
+	auto set_pose = [&](const char *action_name, const char *ar_location_name) {
+		simd_float4x4 anchor_from_location = ar_accessory_anchor_get_anchor_from_location_transform_with_correction(p_controller_anchor, ar_location_name, ar_transform_correction_rendered);
+		Transform3D pose = origin_from_controller_anchor * MTL::simd_to_transform3D(anchor_from_location);
+		p_controller_tracker->set_pose(action_name, pose, Vector3(), Vector3());
+	};
+
+	set_pose("default", ar_accessory_location_name_aim);
+	set_pose("aim", ar_accessory_location_name_aim);
+	set_pose("grip", ar_accessory_location_name_grip);
+	set_pose("palm", ar_accessory_location_name_grip_surface);
+
+	// Button inputs
+	if (p_gc_controller && p_gc_controller.input) {
+		GCControllerLiveInput *input = p_gc_controller.input;
+
+		for (const auto &mapping : button_mappings) {
