+						left_gc_controller = p_controller;
+						if (left_gc_controller != nullptr && left_gc_controller.haptics != nullptr) {
+							left_haptic_engine = [left_gc_controller.haptics createEngineWithLocality:GCHapticsLocalityDefault];
